«OCL»
{result must be a RectifiedGridCoverage or ReferenceableGridCoverage : /* result must be a RectifiedGridCoverage or a ReferenceableGridCoverage */
inv: self.result.oclIsKindOf(RectifiedGridCoverage) OR self.result.oclIsKindOf(ReferenceableGridCoverage)}

«OCL»
